const _kcalCache=new WeakMap();
function kcalOk(r){const m=Number(state.profile.kcalMax);if(!m)return true;let n;if(isLight(r))n=nutri(r,4);else{if(!_kcalCache.has(r))_kcalCache.set(r,nutri(r,4));n=_kcalCache.get(r)}return !n||n.kcal<=m*1.1}
// Alternatives : Daily propose de remplacer un légume que l'utilisateur n'aime pas
const LEGUMES_APP=['carottes','courgettes','haricots verts','brocoli','épinards','poivrons','tomates','champignons de Paris','aubergine','poireaux'];
