function appBase(){return location.origin+location.pathname}
function b64u(o){return btoa(unescape(encodeURIComponent(JSON.stringify(o)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function unb64u(t){t=t.replace(/-/g,'+').replace(/_/g,'/');while(t.length%4)t+='=';return JSON.parse(decodeURIComponent(escape(atob(t))))}
function listLink(){const rows=shopRows().filter(x=>!state.shopping.checked[x.key]).map(x=>[x.name,fmt(x.qty),x.unit]);return appBase()+'#l='+b64u(rows)}
function recipeLink(i){return appBase()+'#r='+i}
function recipeText(i){const r=state.recipes[i],p=state.profile.people||4;return `🍽️ ${r[1]}\n⏱️ ${r[2]} min\n\nIngrédients (${p} pers.) :\n${ings(r,p).map(x=>`• ${x.name} ${fmt(x.qty)} ${x.unit}`).join('\n')}\n\nPréparation :\n${steps(r).map((x,n)=>`${n+1}. ${x.text}`).join('\n')}\n\n👉 La recette dans Swipe Repas : ${recipeLink(i)}`}
function copyText(t,msg){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(t).then(()=>toast(msg),()=>prompt('Copie ce texte :',t));else prompt('Copie ce texte :',t)}
function inboxBox(){const l=state.inbox;if(!l||!l.length)return'';return `<section class="panel">${dailySay('coucou',`On t’a envoyé une liste de courses de <b>${l.length} article${l.length>1?'s':''}</b> !`)}${l.slice(0,12).map(x=>`<p>☐ ${x[0]} ${x[1]} ${x[2]}</p>`).join('')}${l.length>12?`<p class="muted">… et ${l.length-12} autres</p>`:''}<div class="actions"><button class="btn" data-inboxadd>➕ Ajouter à ma liste</button><button class="btn secondary" data-inboxno>Ignorer</button></div></section>`}
function openFromLink(){const h=location.hash||'';let m;try{if((m=h.match(/^#r=(\d+)/))&&state.recipes[Number(m[1])]){state.modal=Number(m[1])}else if((m=h.match(/^#l=([\w-]+)/))){state.inbox=unb64u(m[1]);if(state.view!=='daily')state.view='shopping'}else if((m=h.match(/^#recipe=(\d+)/))&&state.recipes[Number(m[1])]){state.modal=Number(m[1])}}catch(e){toast('Lien illisible')}if(h)history.replaceState(null,'',location.pathname+location.search)}
function nutLine(r,p){const n=nutri(r,p);return n?`🔥 ${n.kcal} kcal · 💪 ${n.prot} g prot. · 🍞 ${n.gluc} g gluc. · 🥑 ${n.lip} g lip. <small>(${meta(r).entier?'par part':'par portion'}${isLight(r)?' · version allégée':''})</small>`:'🔥 kcal non calculées'}
function achatQty(v,name){const e=ING[name];if(!e||!e.a)return v;const[t,lab,pg]=e.a;if(t==='placard')return{...v,name,qty:'',unit:'(placard)'};const g=v.unit==='g'||v.unit==='ml'?v.qty:(e.u&&e.u[v.unit]!=null?v.qty*e.u[v.unit]:null);if(g==null)return v;const n=t==='piece'&&v.unit==='pce'?v.qty:Math.max(1,Math.round(g/pg));return{...v,name,qty:n,unit:t==='piece'&&n>1?lab+'s':n>1?'× '+lab:lab}}
function toast(t){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.appendChild(e);setTimeout(()=>e.remove(),2300)}
function curated(){const d=[['Wrap poulet César','filets de poulet','salade romaine','sauce yaourt'],['Wrap poulet avocat','filets de poulet','avocat','tomates'],['Wrap poulet crudités','filets de poulet','carottes','concombre'],['Wrap saumon avocat','saumon','avocat','concombre'],['Wrap thon crudités','thon en conserve','tomates','laitue'],['Wrap falafel','falafels','laitue','tomates'],['Wrap houmous légumes','houmous','poivrons','courgettes'],['Wrap œuf avocat','œufs','avocat','tomates'],['Wrap dinde moutarde','escalope de dinde','laitue','moutarde'],['Wrap tofu croquant','tofu ferme','carottes','concombre'],['Burrito poulet','poulet émincé','riz','haricots rouges en boîte'],['Burrito bœuf','bœuf haché','riz','haricots rouges en boîte'],['Burrito chili','bœuf haché','haricots rouges en boîte','maïs doux'],['Burrito végétarien','tofu ferme','haricots rouges en boîte','maïs doux'],['Burrito haricots rouges','haricots rouges en boîte','riz','poivrons'],['Burrito poulet épicé','poulet émincé','riz','poivrons'],['Burrito dinde avocat','dinde émincée','avocat','tomates'],['Burrito saumon frais','saumon','riz','avocat'],['Wrap bœuf poivrons','bœuf émincé','poivrons','laitue'],['Wrap lentilles feta','lentilles cuites','feta','tomates']];return d.map(a=>{const st=[{text:'Réchauffe les tortillas pour les assouplir.',timer:1},{text:`Prépare ${a[1]}, ${a[2]} et ${a[3]}.`,timer:0},{text:`Fais cuire ou réchauffe ${a[1]}.`,timer:8},{text:'Répartis la garniture au centre de la tortilla.',timer:0},{text:'Rabats les côtés, roule puis dore à la poêle.',timer:3},{text:'Coupe en deux et sers.',timer:0}];return['🌯',a[0],20,'midi,wrap,burrito,mexicain',`tortillas;4;pce;E|${a[1]};600;g;E|${a[2]};200;g;E|${a[3]==='moutarde'?'moutarde;2;c. à soupe;E':a[3]+';150;g;E'}`,st.map(x=>x.text).join('. '),'',450,25,45,14,{form:'wrap',image:'./assets/recipes/wrap.png',steps:st}]})}
const allowed=r=>!(r&&r[11]&&r[11].quarantaine)&&!state.profile.allergies.some(x=>text(r).includes(norm(x)))&&dietOk(r)&&kcalOk(r), aliases=v=>{const q=norm(v);if(q.includes('wrap'))return['wrap'];if(q.includes('burrito')||q.includes('bourrito'))return['burrito'];return q.split(/[,;/+]| et /).map(x=>x.trim()).filter(Boolean)};
function nav(){return `<nav class="nav">${[['home','🏠 Accueil'],['weekSetup','📅 Semaine'],['now','🍳 Maintenant'],['search','🔎 Recherche'],['planning','🗓️ Planning'],['shopping','🛒 Courses'],['pantry','🥫 Garde-manger'],['profile','👤 Profil']].map(x=>`<button data-go="${x[0]}" class="${state.view===x[0]?'on':''}">${x[1]}</button>`).join('')}</nav>`}
function home(){return `<div class="brand"><img src="./assets/icons/icon-192.png"><div><h1>Swipe Repas</h1><div class="muted">Beta 5.29.0</div></div></div>${dailySay('coucou',`Bonjour ! Qu’est-ce qu’on cuisine aujourd’hui ?`)}<section class="panel"><span class="eyebrow">TON ASSISTANT REPAS</span><h2>Qu’est-ce qu’on cuisine ?</h2><div class="home-actions"><button class="home-choice primary" data-go="weekSetup"><span>📅</span><b>Je prépare ma semaine</b><small>Swipe, planning et courses</small></button><button class="home-choice" data-go="now"><span>🍳</span><b>Je cuisine maintenant</b><small>À partir de ce que tu as</small></button></div></section>`}
const PREF_SUG={loved:['poulet','pâtes','riz','pommes de terre','tomates','fromage','curry','plats au four'],disliked:['champignons','fenouil','coriandre','aubergine','brocoli','épinards','poisson','tofu','olives'],allergies:['lait','œufs','arachides','fruits à coque','poisson','crustacés','soja','gluten','sésame']};function prefSuggestions(k){return `<div class="chips">${(PREF_SUG[k]||[]).map(x=>`<button class="chip ${(state.profile[k]||[]).includes(x)?'on':''}" data-prefquick="${k}|${x}">${x}</button>`).join('')}</div>`}
function profile(){const f=(k,l)=>`<div class="field"><label>${l}</label><input data-prof="${k}" value="${(state.profile[k]||[]).join(', ')}"></div>`;return `<h1>👤 Mon profil</h1>${dailySay('base','Tu peux tout changer ici, je m’adapte tout de suite.')}<section class="panel"><div class="field"><label>Régime</label>${dChips('diet',DIETS,false)}</div><div class="field"><label>Objectif</label>${dChips('goal',GOALS,false)}</div><div class="field"><label>Maximum de kcal par repas (facultatif, marge de 10 %)</label><input type="number" min="200" max="2000" step="50" data-dkcal value="${state.profile.kcalMax||''}" placeholder="ex. 600"></div><button class="btn secondary" data-dailyagain>🧑‍🍳 Refaire la présentation avec Daily</button></section><section class="panel"><div class="field"><label>Personnes habituelles</label><input type="number" min="1" max="12" data-profpeople value="${state.profile.people}"></div>${f('allergies','🚫 Allergies / interdictions')}${prefSuggestions('allergies')}${f('loved','❤️ J’aime')}${prefSuggestions('loved')}${f('disliked','👎 J’évite')}${prefSuggestions('disliked')}${f('family','👨‍👩‍👧‍👦 Membres de la famille')}<div class="field"><label>Équipement</label><input data-prof="equipment" value="${state.profile.equipment.join(', ')}" placeholder="four, wok, airfryer…"></div></section>`}
function weekSetup(){const w=state.week,n=state.weekStep;let body='';if(n===0)body=`<h1>📅 Préparer la semaine</h1><section class="panel"><span class="eyebrow">1/7 · MIDI</span><h2>Combien de midis ?</h2><div class="grid2"><div class="field"><label>Repas</label><input type="number" min="0" max="7" data-w="midMeals" value="${w.midMeals}"></div><div class="field"><label>Personnes</label><input type="number" min="1" max="12" data-w="midPeople" value="${w.midPeople}"></div></div></section>`;if(n===1)body=`<h1>☀️ Tes midis</h1><section class="panel"><span class="eyebrow">2/7 · STYLE</span><h2>Varier ou garder un type ?</h2><div class="field"><select data-w="midMode"><option value="varied" ${w.midMode==='varied'?'selected':''}>✨ Varier</option><option value="type" ${w.midMode==='type'?'selected':''}>🎯 Type précis</option></select></div>${w.midMode==='type'?`<div class="field"><label>Type recherché</label><input data-w="midType" value="${w.midType}" placeholder="wrap, burrito, salade…"></div>`:''}</section>`;if(n===2)body=`<h1>🌙 Les soirs</h1><section class="panel"><span class="eyebrow">3/7 · SOIR</span><div class="grid2"><div class="field"><label>Repas</label><input type="number" min="0" max="7" data-w="eveMeals" value="${w.eveMeals}"></div><div class="field"><label>Personnes</label><input type="number" min="1" max="12" data-w="evePeople" value="${w.evePeople}"></div></div></section>`;if(n===3)body=`<h1>❤️ Une envie ?</h1><section class="panel"><span class="eyebrow">4/7 · ENVIES</span><div class="field"><input data-w="wish" value="${w.wish}" placeholder="italien, asiatique, léger…"></div></section>`;if(n===4)body=`<h1>⏱️ Temps disponible</h1><section class="panel"><span class="eyebrow">5/7 · TEMPS</span><select data-w="time">${[20,30,45,60,90].map(x=>`<option ${w.time===x?'selected':''}>${x}</option>`).join('')}</select></section>`;if(n===5)body=`<h1>🍰 Extras</h1><section class="panel"><span class="eyebrow">6/7 · DESSERTS & BOISSONS</span><div class="grid2"><div class="field"><label>Desserts</label><input type="number" min="0" max="7" data-w="desserts" value="${w.desserts}"></div><div class="field"><label>Eaux détox</label><input type="number" min="0" max="7" data-w="detox" value="${w.detox}"></div><div class="field"><label>Énergisantes</label><input type="number" min="0" max="7" data-w="energy" value="${w.energy}"></div></div></section>`;if(n===6)body=`<h1>✨ Récapitulatif</h1><section class="panel"><span class="eyebrow">7/7 · PRÊT</span><p>☀️ ${w.midMeals} midi(s) · ${w.midMode==='type'?(w.midType||'type à préciser'):'variés'}</p><p>🌙 ${w.eveMeals} soir(s)</p><p>🍰 ${w.desserts} dessert(s) · 🌿 ${w.detox} détox · ⚡ ${w.energy} énergisante(s)</p><p>⏱️ ${w.time} min max</p></section><button class="btn wide" data-startweek>❤️ Commencer le swipe</button>`;return `${body}<div class="slide-nav">${n>0?'<button class="btn secondary" data-weekback>← Retour</button>':'<button class="btn secondary" data-go="home">← Accueil</button>'}${n<6?'<button class="btn" data-weeknext>Continuer →</button>':''}</div>`}
function phasePool(p){const used=new Set(state.saved.map(x=>x.id));let a=state.recipes.filter((r,i)=>allowed(r)&&!used.has(i)&&!state.skipNext.includes(i)&&(state.week.time===90||Number(r[2])<=state.week.time));if(p.type==='meal')a=a.filter(r=>!norm(r[3]).includes('dessert')&&!norm(r[3]).includes('boisson_')&&!norm(r[3]).split(',').some(x=>x==='sauce'||x==='base'||x==='entree'));else a=a.filter(r=>norm(r[3]).includes(p.type));if(p.slot==='mid'&&state.week.midMode==='type'&&state.week.midType.trim()){const al=aliases(state.week.midType);a=a.filter(r=>al.some(x=>text(r).includes(x)))}if(state.week.wish.trim()&&p.type==='meal'){const q=norm(state.week.wish),b=a.filter(r=>text(r).includes(q));if(b.length>=p.count)a=b}a.sort(()=>Math.random()-.5);return a}
function startWeek(){if(state.week.midMode==='type'&&!state.week.midType.trim())return toast('Indique le type des repas du midi');state.saved=[];state.planner={};state.phases=[{label:'☀️ Midi',slot:'mid',type:'meal',count:state.week.midMeals,people:state.week.midPeople},{label:'🌙 Soir',slot:'eve',type:'meal',count:state.week.eveMeals,people:state.week.evePeople},{label:'🍰 Dessert',slot:'extra',type:'dessert',count:state.week.desserts,people:state.week.evePeople},{label:'🌿 Détox',slot:'extra',type:'boisson_detox',count:state.week.detox,people:state.week.evePeople},{label:'⚡ Énergisante',slot:'extra',type:'boisson_energisante',count:state.week.energy,people:state.week.evePeople}].filter(x=>x.count>0);state.phaseIndex=0;loadPhase()}
function loadPhase(){const p=state.phases[state.phaseIndex];if(!p){autoPlan();state.view='planning';return render()}state.deck=phasePool(p);state.deckIndex=0;state.phasePicked=0;state.view='swipe';render()}
function swipe(){const p=state.phases[state.phaseIndex],r=state.deck[state.deckIndex];if(!r)return `<div class="empty"><h1>${p&&p.type!=='meal'&&state.deck.length<2?'Bientôt plus de choix':'Aucune autre recette compatible'}</h1><p>${p&&p.type!=='meal'&&state.deck.length<2?'Les desserts et boissons sont en cours de vérification : les recettes trop approximatives ont été retirées. De vraies recettes arrivent bientôt.':''}${p&&p.type!=='meal'&&state.deck.length<2?'':p?.slot==='mid'&&state.week.midMode==='type'?`Plus de recettes « ${state.week.midType} » compatibles.`:'Le catalogue compatible est épuisé.'}</p><button class="btn" data-nextphase>Continuer</button></div>`;return `<div class="swipe-backbar"><button class="btn secondary" data-swipeback>← Retour</button></div><div class="phase"><h2>${p.label}</h2><p>${state.phasePicked}/${p.count} validé(s)</p></div><article class="swipe-card"><div class="swipe-visual"><img src="${img(r)}"></div><div class="swipe-body"><h2>${r[1]}</h2><p class="muted">⏱️ ${r[2]} min · ${nutLine(r,state.profile.people||2)}</p></div></article><div class="swipe-actions"><button class="round" style="border-color:var(--coral)" data-swipe="no">✖️</button><button class="round" style="border-color:var(--green)" data-swipe="yes">❤️</button></div><div class="swipe-extra"><button class="chip" data-addcourse="${state.recipes.indexOf(r)}">🛒 Ajouter les ingrédients aux courses</button></div>`}
function autoPlan(){state.planner={};const used=new Set(),put=(items,suffix,count)=>{let n=0;for(let d=0;d<7&&n<count;d++){const item=items.find(x=>!used.has(x.id));if(!item)break;state.planner[`${d}-${suffix}`]=item.id;used.add(item.id);n++}};put(state.saved.filter(x=>x.slot==='mid'),'0',state.week.midMeals);put(state.saved.filter(x=>x.slot==='eve'),'1',state.week.eveMeals);put(state.saved.filter(x=>x.type==='dessert'),'2',state.week.desserts);put(state.saved.filter(x=>x.type==='boisson_detox'),'3',state.week.detox);put(state.saved.filter(x=>x.type==='boisson_energisante'),'4',state.week.energy);save()}
function card(day,meal,key){const id=state.planner[key],r=id==null?null:state.recipes[id];if(!r)return `<article class="plan-card empty-slot"><div><small>${day} · ${meal}</small><h3>Créneau libre</h3></div></article>`;return `<article class="plan-card"><div class="plan-thumb"><img src="${img(r)}"><button class="plan-img-change" data-change="${key}" title="Changer de recette">🔄</button></div><div><small>${day} · ${meal}</small><h3>${r[1]}</h3><div class="actions"><button class="chip" data-recipe="${id}">📖 Recette</button>${key.endsWith('-0')||key.endsWith('-1')?`<button class="chip" data-cook="${id}">🍳 Cuisiner</button>`:''}<button class="chip" data-move="${key}">↕️ Déplacer</button><button class="chip" data-change="${key}">🔄 Changer</button><button class="chip danger" data-skip="${id}">🚫 Pas la semaine prochaine</button></div></div></article>`}
function replaceSwipe(){const r=state.deck[state.deckIndex];if(!r)return `<h1>Aucune autre recette compatible</h1><button class="btn" data-replacecancel>← Planning</button>`;return `<div class="swipe-backbar"><button class="btn secondary" data-replacecancel>← Annuler</button></div><h2>🔄 Choisir une autre recette</h2><article class="swipe-card"><div class="swipe-visual"><img src="${img(r)}"></div><div class="swipe-body"><h2>${r[1]}</h2><p class="muted">⏱️ ${r[2]} min</p></div></article><div class="swipe-actions"><button class="round" data-replaceno>✖️</button><button class="round" data-replaceyes>❤️</button></div>`}
function planning(){const d=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];return `<h1>🗓️ Mon planning</h1><section class="panel"><h2>Comment organiser ?</h2><div class="actions"><button class="btn" data-autoplan>✨ Générer automatiquement</button><button class="btn secondary" data-manual>✋ Je place moi-même</button></div></section>${state.manualPlanning?manualBin():''}<div class="notice">Midi, soir, dessert et boissons ont des emplacements séparés.</div>${d.map((x,i)=>`<section class="day-block"><h2>${x}</h2>${card(x,'Midi',i+'-0')}${card(x,'Soir',i+'-1')}${card(x,'Dessert',i+'-2')}${card(x,'Eau détox',i+'-3')}${card(x,'Énergisante',i+'-4')}</section>`).join('')}<section class="panel planning-final"><h2>✅ Planning prêt ?</h2><p>Valide pour recalculer la liste de courses avec tous les repas programmés.</p><button class="btn wide" data-validateplanning>🛒 Valider et voir ma liste de courses</button></section>`}
function manualBin(){const placed=new Set(Object.values(state.planner).map(Number)),left=state.saved.filter(x=>!placed.has(x.id));return `<section class="panel"><h2>📥 À programmer</h2>${left.map(x=>`<div class="manual-item"><b>${state.recipes[x.id][1]}</b><button class="chip" data-place="${x.id}">📅 Placer</button></div>`).join('')||'<p class="muted">Tout est programmé.</p>'}</section>`}
function searchType(r){const t=norm(r[3]),k=t.split(',');return k.includes('sauce')||k.includes('base')?'sauce':k.includes('entree')?'entree':t.includes('dessert')?'dessert':t.includes('boisson_detox')?'detox':t.includes('boisson_energisante')?'energy':'meal'}
function searchRows(){const q=norm(state.search.q);return state.recipes.filter(allowed).filter(r=>(!q||text(r).includes(q))&&(state.search.type==='all'||searchType(r)===state.search.type)&&Number(r[2])<=state.search.time).slice(0,80)}
function search(){const rows=searchRows();return `<h1>🔎 Rechercher</h1><section class="panel"><div class="field"><label>Nom ou ingrédient</label><input data-searchq value="${state.search.q}" placeholder="tarte aux pommes, poulet, wrap…"></div><div class="actions">${[['all','Tout'],['meal','Repas'],['entree','Entrées'],['sauce','Sauces et bases'],['dessert','Dessert'],['detox','Détox'],['energy','Énergisante']].map(x=>`<button class="chip ${state.search.type===x[0]?'on':''}" data-searchtype="${x[0]}">${x[1]}</button>`).join('')}</div></section><div data-results>${rows.map(r=>{const i=state.recipes.indexOf(r);return `<article class="search-card"><div class="search-img"><img src="${img(r)}"></div><div><h3>${r[1]}</h3><p class="muted">⏱️ ${r[2]} min</p><div class="actions"><button class="chip" data-recipe="${i}">📖 Voir</button><button class="chip" data-program="${i}">📅 Programmer</button><button class="chip" data-addcourse="${i}">🛒 Courses</button></div></div></article>`}).join('')||'<div class="empty">Aucun résultat.</div>'}</div>`}
const NP=['poulet','dinde','bœuf','porc','veau','agneau','saumon','poisson','thon','tofu'];
const NF={hache:['haché','hache','hachée','hachee'],filet:['filet','filets','escalope','pavé','pave','aiguillette'],morceaux:['morceaux','dés','des','émincé','emince'],cuisse:['cuisse','cuisses'],steak:['steak','bifteck','entrecôte','entrecote'],saucisse:['saucisse','saucisses','merguez','chipolata'],entier:['entier','rôti','roti']};
function nSpecies(v){const n=norm(v);return NP.find(x=>n.includes(norm(x)))||''}
function nForm(v){const n=norm(v);for(const[k,a]of Object.entries(NF))if(a.some(x=>n.includes(norm(x))))return k;return''}
function nTokens(v){return norm(v).split(/[^a-z0-9]+/).filter(x=>x.length>2&&!['frais','fraiche','filet','filets'].includes(x))}
function nStock(name){const w=nTokens(name);return state.stock.find(x=>nTokens(x.name).some(t=>w.includes(t)))}
function nUnits(a,b){return a===b||(['g','kg'].includes(a)&&['g','kg'].includes(b))||(['ml','l'].includes(a)&&['ml','l'].includes(b))}
function nBase(q,u){q=Number(q)||0;return u==='kg'||u==='l'?q*1000:q}
const SUB_RULES=[{from:['épinards','epinards'],to:['haricots verts','brocoli','courgettes'],reliability:'possible',note:'Texture différente : adapte le temps de cuisson.'},{from:['riz'],to:['pâtes','pommes de terre','semoule','quinoa','nouilles'],reliability:'fiable',note:'Accompagnement interchangeable ; adapte le temps de cuisson.'},{from:['pommes de terre'],to:['riz','pâtes','semoule','quinoa'],reliability:'fiable',note:'Accompagnement interchangeable ; adapte le temps de cuisson.'},{from:['carottes'],to:['courgettes','poivrons','haricots verts'],reliability:'possible',note:'Adapte le temps de cuisson selon le légume.'},{from:['tomates concassées','tomates concassees'],to:['tomates'],reliability:'possible',note:'Coupe les tomates et laisse réduire davantage.'},{from:["huile d’olive",'huile olive'],to:['huile de tournesol','huile neutre','huile de colza'],reliability:'fiable',note:'Même quantité pour une cuisson courante.'},{from:['brocoli'],to:['chou-fleur','haricots verts','courgettes'],reliability:'possible',note:'Même rôle de légume ; adapte la cuisson.'},{from:['courgettes'],to:['aubergine','poivrons','haricots verts'],reliability:'possible',note:'Texture différente mais compatible.'},{from:['poivrons'],to:['courgettes','carottes','haricots verts'],reliability:'possible',note:'Adapte cuisson et assaisonnement.'},{from:['semoule'],to:['quinoa','riz','boulgour'],reliability:'fiable',note:'Adapte le temps de cuisson.'},{from:['quinoa'],to:['riz','semoule','boulgour'],reliability:'fiable',note:'Adapte le temps de cuisson.'}];
function subFor(ing){const t=norm(ing.name),out=[];for(const r of SUB_RULES){if(!r.from.some(x=>t.includes(norm(x))))continue;for(const name of r.to){const stock=nStock(name),pantry=state.pantry.find(x=>norm(x).includes(norm(name))||norm(name).includes(norm(x)));out.push({name,reliability:r.reliability,note:r.note,available:!!(stock||pantry)})}}return out}

function nEvaluate(r){if(!allowed(r))return{score:-999,note:'Allergène ou interdiction',missing:[],substitutable:[]};const all=ings(r,state.now.people),pi=all.find(x=>nSpecies(x.name)),ws=nSpecies(state.now.protein),wf=state.now.form,gs=pi?nSpecies(pi.name):'',gf=pi?nForm(pi.name):'';if(ws&&gs!==ws)return{score:-999,note:'Protéine différente',missing:[],substitutable:[]};if(wf&&gf&&wf!==gf)return{score:-999,note:'Forme incompatible',missing:[],substitutable:[]};let score=35,note='Protéine compatible';if(ws){score+=35;note='Même protéine'}if(wf&&gf===wf){score+=45;note+=' · même forme'}const missing=[],substitutable=[];for(const x of all){const st=nStock(x.name),enough=st&&nUnits(st.unit,x.unit)&&nBase(st.qty,st.unit)>=nBase(x.qty,x.unit);if(enough){score+=22;continue}const availableSubs=subFor(x).filter(a=>a.available);if(availableSubs.length){score-=3;substitutable.push({ingredient:x,options:availableSubs})}else{score-=18;missing.push(x)}}let sideMatches=0;for(const x of state.now.starches)if(text(r).includes(norm(x))){score+=30;sideMatches++}for(const x of state.now.vegetables)if(text(r).includes(norm(x))){score+=20;sideMatches++}if((state.now.starches.length||state.now.vegetables.length)&&sideMatches===0)score-=35;for(const x of state.profile.loved||[])if(text(r).includes(norm(x)))score+=4;for(const x of state.profile.disliked||[])if(text(r).includes(norm(x)))score-=12;return{score,note,missing,substitutable}}
function nowResults(){return state.recipes.map((r,i)=>({r,i,e:nEvaluate(r)})).filter(x=>x.e.score>0).sort((a,b)=>(a.e.missing.length-b.e.missing.length)||(b.e.substitutable.length-a.e.substitutable.length)||(b.e.score-a.e.score)).slice(0,40)}
function nPick(k,a){return `<div class="chips">${a.map(x=>`<button class="chip ${state.now[k].includes(x)?'on':''}" data-ntoggle="${k}|${x}">${x}</button>`).join('')}</div>`}
function now(){const n=state.now;if(n.step==='people')return `<h1>🍳 Je cuisine maintenant</h1><section class="panel"><span class="eyebrow">1/5 · PERSONNES</span><h2>Pour combien de personnes ?</h2><input type="number" min="1" max="12" data-npeople value="${n.people}"><div class="slide-nav"><button class="btn secondary" data-go="home">← Accueil</button><button class="btn" data-nnext="protein">Continuer →</button></div></section>`;if(n.step==='protein')return `<h1>🥩 Protéine disponible</h1><section class="panel"><span class="eyebrow">2/5 · PROTÉINE</span><div class="chips">${NP.map(x=>`<button class="chip ${n.protein===x?'on':''}" data-nprotein="${x}">${x}</button>`).join('')}</div><div class="slide-nav"><button class="btn secondary" data-nback="people">← Retour</button><button class="btn" data-nnext="form">Continuer →</button></div></section>`;if(n.step==='form')return `<h1>🔪 Forme et quantité</h1><section class="panel"><span class="eyebrow">3/5 · FORME</span><div class="chips">${Object.keys(NF).map(x=>`<button class="chip ${n.form===x?'on':''}" data-nform="${x}">${x}</button>`).join('')}</div><div class="grid2"><div class="field"><label>Quantité</label><input type="number" data-nqty value="${n.qty}"></div><div class="field"><label>Unité</label><select data-nunit>${['g','kg','pce'].map(x=>`<option ${n.unit===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="slide-nav"><button class="btn secondary" data-nback="protein">← Retour</button><button class="btn" data-nsave>Continuer →</button></div></section>`;if(n.step==='sides')return `<h1>🥔 Accompagnements</h1><section class="panel"><span class="eyebrow">4/5 · DISPONIBLE</span><h2>Féculents</h2>${nPick('starches',['riz','pâtes','pommes de terre','semoule','quinoa','nouilles'])}<h2>Légumes</h2>${nPick('vegetables',['carottes','courgettes','brocoli','épinards','poivrons','tomates','haricots verts'])}<div class="slide-nav"><button class="btn secondary" data-nback="form">← Retour</button><button class="btn" data-nsearch>Rechercher →</button></div></section>`;const rows=nowResults();return `<h1>✅ Recettes compatibles</h1><p class="muted">Classées selon la protéine, sa forme, la quantité, le stock et les accompagnements.</p><button class="btn secondary" data-nback="sides">← Modifier</button>${rows.map(x=>`<article class="search-card"><div class="search-img"><img src="${img(x.r)}"></div><div><h3>${x.r[1]}</h3><p>${x.e.note} · score ${x.e.score}</p><p class="muted">${x.e.missing.length?x.e.missing.length+' ingrédient(s) réellement manquant(s)':x.e.substitutable.length?x.e.substitutable.length+' remplacement(s) disponible(s)':'Tout semble disponible'}</p>${x.e.substitutable.length?`<div class="sub-preview"><b>🔄 Substituts disponibles</b>${x.e.substitutable.slice(0,3).map(z=>`<small>${z.ingredient.name} → ${z.options.map(o=>o.name).join(' ou ')}</small>`).join('')}</div>`:''}<div class="actions"><button class="chip" data-nvalidate="${x.i}">✅ Vérifier</button><button class="chip" data-cook="${x.i}">🍳 Cuisiner</button></div></div></article>`).join('')||'<section class="panel">Aucune recette compatible.</section>'}`}
function nowCheck(){const i=state.now.validationId,r=state.recipes[i],ev=nEvaluate(r);return `<h1>✅ Vérifie avant de cuisiner</h1><section class="panel"><h2>${r[1]}</h2><p>${ev.note}</p><button class="btn secondary" data-nback="sides">← Modifier ce que j’ai</button>${ings(r,state.now.people).map((x,n)=>{const key=`${i}|${n}`,added=state.now.validationAdds[key],sub=state.now.substitutions[key],st=added||nStock(x.name),ok=!!sub||(st&&nUnits(st.unit,x.unit)&&nBase(st.qty,st.unit)>=nBase(x.qty,x.unit)),ss=!ok?subFor(x):[];return `<div class="validation-row ${ok?'ok':'miss'}"><b>${ok?'✅':'⚠️'} ${x.name}</b><span>${fmt(x.qty)} ${x.unit}</span><small>${sub?`Remplacé par : ${sub.name}`:ok?`Disponible : ${st.qty} ${st.unit}`:'Manquant ou insuffisant'}</small>${!ok?`<div class="check-actions"><button class="chip" data-ni-have="${key}">✅ Je l’ai</button><button class="chip" data-ni-dont="${key}">❌ Je ne l’ai pas</button></div>`:''}${ss.length&&!ok?`<div class="sub-zone"><b>🔄 Substituts</b><div class="chips">${ss.map(a=>`<button class="chip ${a.available?'on':''}" data-nsub="${key}|${a.name}" data-nsubnote="${a.note}">${a.name} · ${a.reliability}${a.available?' · ✓ disponible':''}</button>`).join('')}</div></div>`:''}${added?.editing?`<div class="confirm-stock"><input type="number" data-ni-qty="${key}" placeholder="Quantité"><select data-ni-unit="${key}">${['g','kg','ml','l','pce'].map(u=>`<option ${u===x.unit?'selected':''}>${u}</option>`).join('')}</select><button class="btn" data-ni-confirm="${key}">Valider</button></div>`:''}</div>`}).join('')}<div class="actions"><button class="btn" data-recipe="${i}">📖 Recette</button><button class="btn secondary" data-cook="${i}">🍳 Mode cuisine</button><button class="btn secondary" data-nback="results">← Résultats</button></div></section>`}
function pantry(){const quick=['sel','poivre','huile d’olive','farine','sucre','pâtes','riz','ail','oignons','moutarde','paprika','curry'];return `<h1>🥫 Garde-manger</h1><section class="panel"><h2>Essentiels habituels</h2><div class="chips">${quick.map(x=>`<button class="chip ${state.pantry.includes(x)?'on':''}" data-pantry="${x}">${state.pantry.includes(x)?'✓':'＋'} ${x}</button>`).join('')}</div><div class="field"><label>Ajouter librement</label><div class="actions"><input data-pantrycustom><button class="btn" data-addpantry>Ajouter</button></div></div></section><section class="panel"><h2>Stock précis</h2>${state.stock.map((x,i)=>`<div class="stock-card"><b>${x.name}</b><span>${x.qty} ${x.unit}</span><button class="chip" data-delstock="${i}">✕</button></div>`).join('')}<button class="btn secondary" data-addstock>＋ Ajouter un stock</button></section>`}
function shopCanon(name){let n=norm(name).replace(/\b(filets?|morceaux?|frais|fraiche|cuit|cuite|cru|crue)\b/g,'').replace(/\s+/g,' ').trim();const aliases=[[/galettes? de ble|tortillas?|wraps?/,'tortillas / wraps'],[/boeuf hache|viande hachee de boeuf/,'bœuf haché'],[/pommes? de terre/,'pommes de terre'],[/oignons?/,'oignons'],[/tomates?/,'tomates'],[/courgettes?/,'courgettes'],[/carottes?/,'carottes'],[/poivrons?/,'poivrons'],[/oeufs?/,'œufs']];for(const[a,b]of aliases)if(a.test(n))return b;return n}
function shopBase(q,u){q=Number(q)||0;if(u==='kg')return{qty:q*1000,unit:'g'};if(u==='l')return{qty:q*1000,unit:'ml'};return{qty:q,unit:u==='pièce'||u==='pièces'?'pce':u}}
function shopRayon(name){const n=norm(name);if(/poulet|dinde|boeuf|porc|veau|agneau|poisson|saumon|thon|cabillaud|colin|truite|saucisse|steak|viande hachee|haché|hache/.test(n))return'🥩 Boucherie & poissonnerie';if(/lait|fromage|yaourt|skyr|creme|beurre|oeuf/.test(n))return'🥛 Crèmerie & œufs';if(/tortilla|wrap|pain|pita|naan/.test(n))return'🥖 Pain, wraps & tortillas';if(/pates|riz|semoule|quinoa|boulgour|avoine|lentille|pois chiche|haricot sec|polenta/.test(n))return'🍚 Féculents & légumineuses';if(/pomme de terre|tomate|courgette|carotte|poivron|brocoli|epinard|haricot vert|oignon|ail|fruit|citron|avocat|pomme|banane|fraise|framboise|myrtille|amande/.test(n))return'🥕 Fruits & légumes';if(/paprika|curry|cumin|curcuma|cannelle|poivre|sel|epice|herbe|basilic|persil|coriandre/.test(n))return'🧂 Épices & aromates';if(/huile|moutarde|sauce|vinaigre|sucre|bouillon|miel|concentre/.test(n))return'🥫 Épicerie & condiments';return'🥫 Épicerie'}
function shopRows(){const m={};for(const[key,id]of Object.entries(state.planner)){const people=state.plannerPeople?.[key]??(key.endsWith('-0')?state.week.midPeople:state.week.evePeople),r=state.recipes[id];if(!r)continue;for(const x of ings(r,people)){if(state.pantry.some(y=>shopCanon(y)===shopCanon(x.name)))continue;const b=shopBase(x.qty,x.unit),name=shopCanon(x.name),k=name+'|'+b.unit;m[k]??={key:k,name,qty:0,unit:b.unit,rayon:shopRayon(name),src:x.name};m[k].qty+=b.qty}}for(const st of state.stock){const name=shopCanon(st.name),b=shopBase(st.qty,st.unit),k=name+'|'+b.unit;if(m[k])m[k].qty=Math.max(0,m[k].qty-b.qty)}for(const x of state.shopping.manual){const b=shopBase(x.qty,x.unit),name=shopCanon(x.name),k=name+'|'+b.unit;m[k]??={key:k,name,qty:0,unit:b.unit,rayon:shopRayon(name)};m[k].qty+=b.qty}return Object.values(m).filter(x=>x.qty>0&&!state.shopping.edits[x.key]?.deleted).map(x=>{const e=state.shopping.edits[x.key]||{},v={...achatQty(x,x.src),...e};if(v.unit==='g'&&v.qty>=1000){v.qty=Math.round(v.qty)/1000;v.unit='kg'}else if(v.unit==='ml'&&v.qty>=1000){v.qty=Math.round(v.qty)/1000;v.unit='l'}return v}).sort((a,b)=>a.rayon.localeCompare(b.rayon,'fr')||a.name.localeCompare(b.name,'fr'))}
function shopping(){const rows=shopRows(),groups=rows.reduce((g,x)=>((g[x.rayon]??=[]).push(x),g),{});return `${inboxBox()}<h1>🛒 Liste de courses</h1><p class="muted">Quantités regroupées, unités converties et stock précis déduit automatiquement.</p>${Object.entries(groups).map(([rayon,items])=>`<section class="panel shop-rayon"><h2>${rayon}</h2>${items.map(x=>`<div class="shop-row ${state.shopping.checked[x.key]?'done':''}"><input type="checkbox" data-check="${x.key}" ${state.shopping.checked[x.key]?'checked':''}><input data-shopname="${x.key}" value="${x.name}"><input type="number" step="any" data-shopqty="${x.key}" value="${fmt(x.qty)}"><input data-shopunit="${x.key}" value="${x.unit}"><button class="chip" data-delshop="${x.key}">✕</button></div>`).join('')}</section>`).join('')}<section class="panel"><div class="actions"><button class="btn secondary" data-addshop>＋ Ajouter</button><button class="btn" data-sharelist>📤 Envoyer</button><button class="btn secondary" data-listlink>🔗 Copier le lien</button><button class="btn secondary" data-copylist>📋 Copier</button></div></section>`}
function modal(i){const r=state.recipes[i],p=state.week.evePeople||state.profile.people;return `<div class="modal"><article class="sheet"><button class="chip" data-close>✕</button><img class="hero" src="${img(r)}"><h1>${r[1]}</h1><p>⏱️ ${r[2]} min · ${nutLine(r,p)}</p>${meta(r).attention?`<p class="muted">⚠️ ${meta(r).attention}</p>`:''}${dailyAlt(r)}<h2>Ingrédients</h2>${meta(r).entier?`<p class="muted">Recette entière : ${meta(r).portions} parts</p>`:''}${ings(r,p).map(x=>`<p>${x.name} <b>${fmt(x.qty)} ${x.unit}</b></p>`).join('')}${lightBox(r,i)}${sauceBox(r)}<h2>Préparation</h2>${isLight(r)?`<p class="muted">🥗 Version allégée : ${meta(r).allege.changes.map(c=>c.vers===c.de?`${c.de} en moins (voir la liste)`:`${c.de} → ${c.vers}`).join(' ; ')} dans les étapes.</p>`:''}${steps(r).map((x,n)=>`<div class="step"><span>${n+1}</span><div><p>${x.text}</p>${x.timer?`<button class="chip" data-timer="${x.timer}">⏱️ ${x.timer} min</button>`:''}</div></div>`).join('')}<div class="actions"><button class="btn" data-read="${i}">🔊 Lire</button><button class="btn secondary" data-cook="${i}">🍳 Mode cuisine</button><button class="btn secondary" data-share="${i}">📤 Partager</button><button class="btn secondary" data-copyrecipe="${i}">📋 Copier</button><button class="btn secondary" data-recipelink="${i}">🔗 Lien</button></div><div data-shortbox></div></article></div>`}
function cookView(){const r=state.recipes[state.cook],s=steps(r),x=s[state.cookStep];if(!r||!x){state.cook=null;state.view='home';return home()}return `<h1>🍳 Mode cuisine</h1><section class="panel"><h2>${r[1]}</h2><div class="progress"><i style="width:${((state.cookStep+1)/s.length)*100}%"></i></div><p class="muted">Étape ${state.cookStep+1}/${s.length}</p><div class="cook-step">${x.text}</div>${x.timer?`<button class="btn wide" data-timer="${x.timer}">⏱️ Lancer ${x.timer} min</button>`:''}<div class="actions"><button class="btn secondary" data-cookprev>←</button><button class="btn" data-cooknext>Étape suivante →</button></div></section>`}
function render(){const body=state.cook!=null?cookView():state.view==='home'?home():state.view==='weekSetup'?weekSetup():state.view==='swipe'?swipe():state.view==='replaceSwipe'?replaceSwipe():state.view==='planning'?planning():state.view==='search'?search():state.view==='now'?now():state.view==='nowCheck'?nowCheck():state.view==='pantry'?pantry():state.view==='shopping'?shopping():state.view==='profile'?profile():state.view==='daily'?dailyOnboarding():home();app.innerHTML=(state.view==='daily'||state.view==='home'?'':topBar())+body+(state.view==='daily'?'':nav())+(state.modal!=null?modal(state.modal):'')}
function addRecipeCourses(i,people){for(const x of ings(state.recipes[i],people)){state.shopping.manual.push({key:'r-'+Date.now()+'-'+Math.random(),...x})}save();toast('Ingrédients ajoutés aux courses')}function program(i){const raw=prompt('Jour et repas ? Ex. mercredi soir');if(!raw)return;const n=norm(raw),d=['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'],di=d.findIndex(x=>n.includes(x));if(di<0)return toast('Jour non reconnu');const peopleRaw=prompt('Pour combien de personnes ? (Annuler = ignorer l’ajout au planning)',String(state.profile.people||2));if(peopleRaw===null)return toast('Ajout au planning ignoré');const people=Math.max(1,Math.min(12,Number(peopleRaw)||state.profile.people||2)),key=di+'-'+(n.includes('soir')?'1':'0');state.planner[key]=i;state.plannerPeople??={};state.plannerPeople[key]=people;save();toast('Recette programmée pour '+people+' personne(s)');if(confirm('Ajouter les ingrédients de cette recette à la liste de courses ?'))addRecipeCourses(i,people)}
